/**
 * Incident Severity Alert Flow
 *
 * This flow triggers when an incident with empty origin is created and:
 * 1. Logs the short description of the incident
 * 2. If severity is High (1):
 *    - Sends email to assignment group manager with urgent subject
 *    - Sends SMS to all additional assignees
 *    - Updates work notes with notification details
 * 3. Else if severity is Medium (2):
 *    - Sends SMS to all additional assignees
 * 4. Updates incident state to In Progress
 *
 * Triggers when a new incident with empty origin is created
 */

import { action, Flow, wfa, trigger } from '@servicenow/sdk/automation'

export const incidentSeverityAlertFlow = Flow(
    {
        $id: Now.ID['incident_severity_alert_flow'],
        name: 'Incident Severity Alert Flow',
        description: 'Alerts managers and team members based on incident severity for incidents with empty origin',
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['empty_origin_incident_trigger'] },
        {
            table: 'incident',
            condition: 'origin=NULL',
            run_flow_in: 'background',
        }
    ),
    (params) => {
        // Step 1: Log the short description of the incident created
        wfa.action(
            action.core.log,
            {
                $id: Now.ID['log_incident_short_description'],
                annotation: 'Log short description of the incident created',
            },
            {
                log_level: 'info',
                log_message: `Incident created with short description: ${wfa.dataPill(params.trigger.current.short_description, 'string')}`,
            }
        )

        // Step 2: Check if severity is High (1)
        wfa.flowLogic.if(
            {
                condition: `${wfa.dataPill(params.trigger.current.severity, 'string')}=1`,
                annotation: 'Check if incident severity is High (1)',
                $id: Now.ID['check_severity_high'],
            },
            () => {
                // Look up the assignment group to get the manager
                const assignmentGroup = wfa.action(
                    action.core.lookUpRecord,
                    {
                        $id: Now.ID['lookup_assignment_group'],
                        annotation: 'Retrieve assignment group details',
                    },
                    {
                        table: 'sys_user_group',
                        conditions: `sys_id=${wfa.dataPill(params.trigger.current.assignment_group, 'reference')}`,
                    }
                )

                // Look up the manager details
                const manager = wfa.action(
                    action.core.lookUpRecord,
                    {
                        $id: Now.ID['lookup_manager_details'],
                        annotation: 'Retrieve manager details',
                    },
                    {
                        table: 'sys_user',
                        conditions: `sys_id=${wfa.dataPill(assignmentGroup.Record.manager, 'reference')}`,
                    }
                )

                // Send notification to the manager
                wfa.action(
                    action.core.sendNotification,
                    {
                        $id: Now.ID['send_urgent_email_to_manager'],
                        annotation: 'Send urgent notification to assignment group manager',
                    },
                    {
                        table_name: 'incident',
                        record: `${wfa.dataPill(params.trigger.current.sys_id, 'reference')}`,
                        notification: 'high_severity_incident_manager_notification',
                    }
                )

                // Send SMS to all members in the additional assignee list
                wfa.flowLogic.forEach(
                    wfa.dataPill(params.trigger.current.additional_assignee_list, 'array.string'),
                    {
                        $id: Now.ID['foreach_additional_assignees_high'],
                        annotation: 'Send SMS to each additional assignee',
                    },
                    () => {
                        // Look up each assignee to get their phone number
                        const assignee = wfa.action(
                            action.core.lookUpRecord,
                            {
                                $id: Now.ID['lookup_assignee_details_high'],
                                annotation: 'Retrieve assignee phone number',
                            },
                            {
                                table: 'sys_user',
                                conditions: `sys_id=${wfa.dataPill(params.trigger.current.additional_assignee_list, 'array.string')}`,
                            }
                        )

                        // Send SMS to assignee
                        wfa.action(
                            action.core.sendSms,
                            {
                                $id: Now.ID['send_sms_to_assignee_high'],
                                annotation: 'Send SMS to additional assignee',
                            },
                            {
                                recipients: `${wfa.dataPill(assignee.Record.phone, 'string')}`,
                                message: `Short description: ${wfa.dataPill(params.trigger.current.short_description, 'string')}`,
                            }
                        )
                    }
                )

                // Get all assignee names for work notes
                const assigneeNames = wfa.action(
                    action.core.lookUpRecords,
                    {
                        $id: Now.ID['lookup_all_assignee_names'],
                        annotation: 'Retrieve all assignee names for work notes',
                    },
                    {
                        table: 'sys_user',
                        conditions: `sys_idIN${wfa.dataPill(params.trigger.current.additional_assignee_list, 'array.string')}`,
                        max_results: 100,
                        sort_column: 'name',
                        sort_type: 'sort_asc',
                    }
                )

                // Update work notes with notification details
                wfa.action(
                    action.core.updateRecord,
                    {
                        $id: Now.ID['update_work_notes_high'],
                        annotation: 'Update work notes with notification details for high severity',
                    },
                    {
                        table_name: 'incident',
                        record: `${wfa.dataPill(params.trigger.current.sys_id, 'reference')}`,
                        values: TemplateValue({
                            work_notes: `An email has been sent to alert the manager assigned to this incident: ${wfa.dataPill(manager.Record.name, 'string')} and an SMS has been sent to all the developers in his/her team: ${wfa.dataPill(assigneeNames.Records, 'reference')}`,
                        }),
                    }
                )
            }
        )

        // Step 3: Else if severity is Medium (2)
        wfa.flowLogic.elseIf(
            {
                condition: `${wfa.dataPill(params.trigger.current.severity, 'string')}=2`,
                annotation: 'Check if incident severity is Medium (2)',
                $id: Now.ID['check_severity_medium'],
            },
            () => {
                // Send SMS to all members in the additional assignee list
                wfa.flowLogic.forEach(
                    wfa.dataPill(params.trigger.current.additional_assignee_list, 'array.string'),
                    {
                        $id: Now.ID['foreach_additional_assignees_medium'],
                        annotation: 'Send SMS to each additional assignee for medium severity',
                    },
                    () => {
                        // Look up each assignee to get their phone number
                        const assignee = wfa.action(
                            action.core.lookUpRecord,
                            {
                                $id: Now.ID['lookup_assignee_details_medium'],
                                annotation: 'Retrieve assignee phone number',
                            },
                            {
                                table: 'sys_user',
                                conditions: `sys_id=${wfa.dataPill(params.trigger.current.additional_assignee_list, 'array.string')}`,
                            }
                        )

                        // Send SMS to assignee
                        wfa.action(
                            action.core.sendSms,
                            {
                                $id: Now.ID['send_sms_to_assignee_medium'],
                                annotation: 'Send SMS to additional assignee for medium severity',
                            },
                            {
                                recipients: `${wfa.dataPill(assignee.Record.phone, 'string')}`,
                                message: `Short description: ${wfa.dataPill(params.trigger.current.short_description, 'string')}`,
                            }
                        )
                    }
                )
            }
        )

        // Step 4: Update the state of the incident to In Progress (2)
        wfa.action(
            action.core.updateRecord,
            {
                $id: Now.ID['update_incident_to_in_progress'],
                annotation: 'Update incident state to In Progress',
            },
            {
                table_name: 'incident',
                record: `${wfa.dataPill(params.trigger.current.sys_id, 'reference')}`,
                values: TemplateValue({
                    state: 2,
                }),
            }
        )
    }
)
